SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0570000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 57, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "57", "printedPageNumber": 57, "pdfPageNumber": 440, "sequenceIndex": 47, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0570100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0570200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0570000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570100-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570200-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن قباث بن أشيم الليثي رضي الله عنه قال قال رسول الله ﷺ صلاة الرجلين يؤم أحدهما صاحبه أزكى عند الله من صلاة أربعة تترى وصلاة أربعة أزكى عند الله من صلاة ثمانية تترى وصلاة ثمانية يؤمهم أحدهم أزكى عند الله من صلاة مائة تترى رواه البزار والطبراني", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570300-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Qubaath bin Ashyam Allaithi (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Two persons performing salaat together with one as Imaam are liked by Allah more than four persons saying salaat individually. Similarly four persons performing salaat with Jamaat are liked by Allah more than eight persons saying it individually. Similarly again, eight persons performing salaat with Jamaat are liked by Allah more than one hundred persons saying it individually.\"\n\nIn another hadith it is said, \"A big Jamaat is more preferred by Allah than a small Jamaat.\" Some people think that there is no harm in having a small Jamaat of their own at their houses or at their business premises. This is not correct, as in the first place they are deprived of the reward of saying salaat in the musjid and secondly, they lose the blessing of salaat with a big Jamaat. The bigger the congregation, the more pleasing it is to Allah. When our sole aim is to achieve the pleasure of Allah, why should we not adopt a manner more pleasing to Him. It is reported in a hadith that Allah is pleased to see three things, namely, a row of worshippers offering salaat with Jamaat, a person busy in salaat at the time of Tahajjud at the dead of night, and a person fighting in the way of Allah.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570400-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570500-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن سهل بن سعد الساعدي رضي الله عنه قال قال رسول الله ﷺ بشر المشائين في الظلم إلى المساجد بالنور التام يوم القيامة رواه ابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570600-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Sahl bin Sa''d (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Give glad tidings to those who go to the musjid frequently during hours of darkness, for they will have perfect light on the Day of Judgement.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}]}'::jsonb);